void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize coordinates
    vec2 uv = fragCoord / iResolution.xy;
    uv = uv * 2.0 - 1.0; // Shift range to [-1, 1]
    uv.x *= iResolution.x / iResolution.y; // Correct for aspect ratio

    // Convert to polar coordinates
    float angle = atan(uv.y, uv.x);          // Angle around the center
    float radius = length(uv);              // Distance from center

    // Create the tunnel effect
    float speed = 0.5;                      // Speed of tunnel movement
    float time = iTime * speed;             // Time-dependent effect
    float tunnelPattern = mod(radius * 1.0 - time, 1.0); // Repeating pattern in tunnel

    // Distort the angle for a wavy effect
    angle += sin(radius * 1.0 - time) * 0.2;

    // Map the polar coordinates back to UV space for texture sampling
    vec2 textureUV = vec2(angle / 6.2831, tunnelPattern); // Angle (wrapped) and tunnel depth
    textureUV.x += 0.5;                      // Shift angle to [0, 1]

    // Tiling the video texture
    float tileFactor = 3.0;                 // Number of tiles across the texture
    textureUV.x *= tileFactor;                // Scale UVs to create smaller tiles
    textureUV.y *= tileFactor/3.;                // Scale UVs to create smaller tiles

    // Rotate the UV coordinates (90° clockwise)
    vec2 rotatedUV;
    rotatedUV.x = textureUV.y;              // Swap x and y for rotation
    rotatedUV.y = -textureUV.x;

    // Wrap the rotated coordinates to [0, 1] for tiling
    rotatedUV = fract(rotatedUV);

    // Sample the video texture (iChannel0)
    vec4 tex = texture(iChannel0, rotatedUV);

    // Darken the texture based on distance for lighting
    float dist = length(uv);
    vec3 col = tex.rgb * (dist*1.);

    // Apply the sampled texture as the color
     fragColor = vec4(col, 1.0);
}
